detector_raw:
{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "What is the objective of this packing plan — are we minimizing the number of containers used, maximizing the total tons of goods shipped, or something else (e.g., maximizing the number of units shipped)?"
  ],
  "rationale": "The response asks for a single policy choice regarding the optimization objective, presenting mutually exclusive options for one decision."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Do we have to ship all available goods (all 120 A, 90 B, 300 C, 90 D, 120 E), or is it acceptable to leave some units unshipped as long as the containers we do use satisfy the rules?"
  ],
  "rationale": "The response asks a single clarification question regarding whether all goods must be shipped or if partial shipping is allowed."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is the number of containers available unlimited (we can use as many as needed), or is there a fixed fleet size we must work within?"
  ],
  "rationale": "The response asks a single clarification question regarding the availability of containers, presenting a binary choice between unlimited and fixed capacity."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "is it acceptable for a container to be left partially empty (e.g., loaded with only 20 tons out of its 60-ton capacity) as long as it meets the 18-ton minimum, or must each used container be loaded up to some fuller level?"
  ],
  "rationale": "The response asks for a single policy decision regarding the minimum fill level for used containers, presenting two mutually exclusive options that constitute one clarification question."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "The rule says a container with any type A must also contain at least one type C — does this \"at least one\" mean at least one unit of C, or at least one full container's worth (i.e., some larger quantity) of C?"
  ],
  "rationale": "The response asks a single clarification question regarding the specific quantity definition of 'at least one' type C."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "The rule \"each container must contain at least 12 units of type D\" — does this apply to every container that is used, including containers that contain no type A at all?"
  ],
  "rationale": "The response contains a single clarification question asking for the scope of a specific rule."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is it acceptable for some containers to hold more than 12 units of D (e.g., one container holds 18 D while another holds 12), as long as every container has at least 12?"
  ],
  "rationale": "The response contains a single clarification question asking whether variable quantities of D (above the minimum) are allowed per container."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "The rule \"if a container contains any type A then it must also contain at least one type C\" — is this one-way only (A implies C), meaning a container can contain C without A, or is it two-way (A and C must always appear together in the same container)?"
  ],
  "rationale": "The response asks for a single policy choice regarding the directionality of the constraint between types A and C."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Are the goods of each type divisible (i.e., can we split a unit of a goods type across two containers), or must each unit of a given type be assigned entirely to a single container?"
  ],
  "rationale": "The response asks a single clarification question regarding the divisibility of goods units, presenting a binary choice (divisible vs. indivisible) which constitutes one independent semantic query."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Are the goods of each type identical and interchangeable (i.e., any unit of type A is equivalent to any other unit of type A), or are there sub-categories or special constraints within a type that I should be aware of?"
  ],
  "rationale": "The response contains a single clarification question asking about the interchangeability of goods within types, presented as an either/or choice regarding the nature of the units."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Is there any constraint on which goods types can or cannot be placed together in the same container, other than the A→C rule and the minimum-12-D rule already stated?"
  ],
  "rationale": "The response contains a single clarification question asking about additional co-location constraints."
}
